'use strict';
(() => {
  const el=id=>document.getElementById(id);
  const LIMIT=300000, TOKEN='[LINK DELLE PROMO]';
  const DEFAULT_MESSAGE=`🚗 PROMO DEL GIORNO! 🔥\n\nSono disponibili le nuove offerte dedicate.\n👉 Scopri tutte le promo di oggi qui:\n${TOKEN}\n\n💣 Le seguenti promo saranno caricate automaticamente a web. Approfittane ora!`;
  let slots=[null,null,null,null],revision=0,busy=false,collage=null,previousLink='',thumbUrls=[];
  function validateLink(value){try{const u=new URL(value.trim());return u.protocol==='https:'&&['postimg.cc','postimages.org','i.postimg.cc'].includes(u.hostname)&&u.pathname!=='/'?u.href:null}catch{return null}}
  function extractLink(value){const urls=String(value).match(/https:\/\/[^\s"'<>\[\]]+/g)||[];return urls.map(validateLink).find(u=>u&&new URL(u).hostname==='postimg.cc')||null}
  function messageWithLink(message,link,oldLink){if(oldLink&&message.includes(oldLink))return message.replace(oldLink,link);if(message.includes(TOKEN))return message.replace(TOKEN,link);const line=/((?:👉\s*)?Scopri tutte le promo di oggi qui:\s*\n)(?:https:\/\/\S+|\[LINK DELLE PROMO\])/;if(line.test(message))return message.replace(line,(_,prefix)=>prefix+link);return message+'\n\n'+link}
  function setLink(link){const valid=validateLink(link);if(!valid){el('postimagesLink').setCustomValidity('Inserisci un link HTTPS valido di Postimages');return false}el('postimagesLink').setCustomValidity('');el('postimagesLink').value=valid;el('broadcastText').value=messageWithLink(el('broadcastText').value,valid,previousLink);previousLink=valid;return true}
  function clearLink(){if(previousLink)el('broadcastText').value=el('broadcastText').value.replace(previousLink,TOKEN);previousLink='';el('postimagesLink').value='';el('postimagesLink').setCustomValidity('')}
  function state(){const count=slots.filter(Boolean).length;el('dailyCount').textContent=count+' / 4';el('addDaily').disabled=busy||count===4;el('importDaily').disabled=busy||count===4;el('clearDaily').disabled=busy||count===0;el('buildCollage').disabled=busy||count!==4;el('downloadCollage').disabled=busy||!collage;el('uploadPostimages').disabled=busy||!collage;el('uploadPostimages').textContent=busy?'Operazione in corso…':'Crea link Postimages'}
  function invalidate(){revision++;collage=null;el('collageCanvas').hidden=true;clearLink();el('collageStatus').textContent=slots.filter(Boolean).length===4?'Le quattro promo sono pronte: crea il collage.':'Aggiungi 4 locandine per creare il collage.';state()}
  function blobFor(c,type='image/jpeg',q=.92){return new Promise((resolve,reject)=>c.toBlob(b=>b?resolve(b):reject(Error('Impossibile generare l’immagine.')),type,q))}
  async function decode(blob){const url=URL.createObjectURL(blob);try{return await new Promise((resolve,reject)=>{const img=new Image();img.onload=()=>resolve(img);img.onerror=()=>reject(Error('Immagine non leggibile.'));img.src=url})}finally{URL.revokeObjectURL(url)}}
  function save(){try{const req=indexedDB.open('cida-daily-collage',1);req.onupgradeneeded=()=>req.result.createObjectStore('daily');req.onsuccess=()=>{const db=req.result;const tx=db.transaction('daily','readwrite');tx.objectStore('daily').put(slots,'slots');tx.oncomplete=()=>db.close();tx.onerror=()=>{db.close();toast('Raccolta attiva; salvataggio nel browser non disponibile.')}};req.onerror=()=>toast('Raccolta attiva; salvataggio nel browser non disponibile.')}catch{}}
  function paintSlots(){thumbUrls.forEach(URL.revokeObjectURL);thumbUrls=[];el('dailySlots').replaceChildren();slots.forEach((slot,i)=>{const card=document.createElement('div');card.className='daily-slot';if(slot){const img=document.createElement('img');img.src=URL.createObjectURL(slot.blob);thumbUrls.push(img.src);img.alt='Locandina '+(i+1);card.append(img)}else{const empty=document.createElement('div');empty.className='daily-empty';empty.textContent='＋';card.append(empty)}const name=document.createElement('p');name.textContent=(i+1)+'. '+(slot?slot.title:'Slot libero');card.append(name);const buttons=document.createElement('div');buttons.className='slot-buttons';const button=(label,fn)=>{const b=document.createElement('button');b.className='ghost';b.textContent=label;b.disabled=busy;b.onclick=fn;buttons.append(b)};button(slot?'Sostituisci':'Aggiungi qui',()=>capture(i));if(slot){if(i>0)button('←',()=>swap(i,i-1));if(i<3)button('→',()=>swap(i,i+1));button('Rimuovi',()=>{if(busy)return;slots[i]=null;invalidate();paintSlots();save()})}card.append(buttons);el('dailySlots').append(card)});state()}
  function swap(a,b){if(busy)return;[slots[a],slots[b]]=[slots[b],slots[a]];invalidate();paintSlots();save()}
  async function capture(index){if(busy)return;if(!base.complete||!base.naturalWidth){toast('Attendi il caricamento del modello.');return}busy=true;state();try{render();const blob=await blobFor(canvas,'image/png');slots[index]={title:el('description').value||el('title').value||'Promo CIDA',blob};invalidate();save();toast('Locandina aggiunta allo slot '+(index+1))}catch(e){toast(e.message)}finally{busy=false;paintSlots()}}
  el('addDaily').onclick=()=>{const index=slots.findIndex(x=>!x);if(index>=0)capture(index)};
  el('clearDaily').onclick=()=>{if(busy)return;slots=[null,null,null,null];invalidate();paintSlots();save()};
  el('importDaily').onchange=async e=>{if(busy)return;const files=Array.from(e.target.files||[]);e.target.value='';if(!files.length)return;const free=slots.map((s,i)=>s?null:i).filter(i=>i!==null);if(files.length>free.length){toast('Ci sono '+free.length+' slot liberi. Seleziona al massimo '+free.length+' immagini.');return}busy=true;state();try{const imported=[];for(const file of files){if(!file.type.startsWith('image/')||file.size>12000000)throw Error('Usa immagini PNG/JPG/WebP inferiori a 12 MB.');const img=await decode(file);const c=document.createElement('canvas');c.width=c.height=1080;const cx=c.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,1080,1080);const scale=Math.min(1080/img.width,1080/img.height);cx.drawImage(img,(1080-img.width*scale)/2,(1080-img.height*scale)/2,img.width*scale,img.height*scale);imported.push({title:file.name,blob:await blobFor(c,'image/png')})}imported.forEach((s,i)=>slots[free[i]]=s);invalidate();save();toast('Immagini aggiunte alla raccolta.')}catch(e){toast(e.message)}finally{busy=false;paintSlots()}};
  async function compressCollage(images){for(let size=1600;size>=512;size=Math.floor(size*.85)){const c=document.createElement('canvas');c.width=c.height=size;const cx=c.getContext('2d');cx.fillStyle='#fff';cx.fillRect(0,0,size,size);cx.imageSmoothingEnabled=true;cx.imageSmoothingQuality='high';const margin=6,gap=6,tile=(size-margin*2-gap)/2;images.forEach((img,i)=>{const scale=Math.min(tile/img.width,tile/img.height),w=img.width*scale,h=img.height*scale;cx.drawImage(img,margin+(i%2)*(tile+gap)+(tile-w)/2,margin+Math.floor(i/2)*(tile+gap)+(tile-h)/2,w,h)});let best=await blobFor(c,'image/jpeg',.92);if(best.size<=LIMIT)return{blob:best,size};best=await blobFor(c,'image/jpeg',.35);if(best.size>LIMIT)continue;let lo=.35,hi=.92;for(let n=0;n<7;n++){const q=(lo+hi)/2,b=await blobFor(c,'image/jpeg',q);if(b.size<=LIMIT){lo=q;best=b}else hi=q}return{blob:best,size}}throw Error('Non è stato possibile restare entro 300 KB. Prova immagini meno complesse.')}
  el('buildCollage').onclick=async()=>{if(busy||slots.some(x=>!x))return;busy=true;state();const version=revision;el('collageStatus').textContent='Creo il collage e verifico il limite di 300 KB…';try{const imgs=[];for(const s of slots)imgs.push(await decode(s.blob));const result=await compressCollage(imgs);if(version!==revision)throw Error('La raccolta è cambiata: ricrea il collage.');if(result.blob.size>LIMIT)throw Error('Il collage supera 300 KB.');const img=await decode(result.blob),c=el('collageCanvas');c.width=c.height=result.size;c.getContext('2d').drawImage(img,0,0);c.hidden=false;collage=result;el('collageStatus').textContent=`Collage pronto · ${result.size} × ${result.size} px · ${(result.blob.size/1000).toFixed(1)} KB / 300 KB`;toast('Collage pronto da scaricare.')}catch(e){el('collageStatus').textContent=e.message;toast(e.message)}finally{busy=false;paintSlots()}};
  function collageName(){const d=new Date(),date=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');return 'CIDA_PROMO_DEL_GIORNO_'+date+'.jpg'}
  el('downloadCollage').onclick=()=>{if(collage&&collage.blob.size<=LIMIT)download(collage.blob,collageName())};
  // Popup and postMessage protocol follow Postimages' official phpBB3 integration.
  let postimagesWindow=null,uploadRevision=-1;
  el('uploadPostimages').onclick=()=>{if(busy||!collage)return;const params=new URLSearchParams({mode:'phpbb3',areaid:'cida_daily',hash:'1',pm:'1',lang:'italian',code:'thumb',forumurl:encodeURIComponent(location.href)});if(postimagesWindow&&!postimagesWindow.closed)postimagesWindow.close();postimagesWindow=window.open('https://postimages.org/upload?'+params,'cida_daily','scrollbars=yes,resizable=yes,width=1000,height=720');if(!postimagesWindow){el('postimagesFallback').open=true;toast('Consenti la finestra Postimages oppure usa il caricamento alternativo.');return}uploadRevision=revision;download(collage.blob,collageName());el('collageStatus').textContent=`Collage scaricato · ${(collage.blob.size/1000).toFixed(1)} KB. Nella finestra Postimages scegli questo JPG: il link tornerà nel messaggio.`;toast('Seleziona il collage scaricato nella finestra Postimages.');};
  window.addEventListener('message',event=>{if(event.origin!=='https://postimages.org'||event.source!==postimagesWindow||uploadRevision!==revision)return;const data=event.data;if(!data||data.id!=='cida_daily'||typeof data.message!=='string')return;let message;try{message=decodeURIComponent(data.message)}catch{return}const link=extractLink(message);if(!link||!setLink(link)){el('postimagesFallback').open=true;toast('Copia il link da Postimages e incollalo nel campo dedicato.');return}el('collageStatus').textContent=`Collage pronto · ${(collage.blob.size/1000).toFixed(1)} KB · Link Postimages inserito nel messaggio.`;toast('Link Postimages inserito: puoi copiare il broadcast.');});
  el('postimagesLink').addEventListener('change',()=>{const value=el('postimagesLink').value.trim();if(!value){clearLink();return}if(!setLink(value)){toast('Inserisci il link HTTPS restituito da Postimages.');el('postimagesLink').reportValidity()}});
  el('copyBroadcast').onclick=async()=>{const link=validateLink(el('postimagesLink').value);if(!link){toast('Genera o incolla il link Postimages prima di copiare.');return}setLink(link);try{await navigator.clipboard.writeText(el('broadcastText').value);toast('Messaggio copiato.')}catch{el('broadcastText').focus();el('broadcastText').select();toast('Testo selezionato: premi Ctrl+C o usa Copia.')}};
  el('broadcastText').value=DEFAULT_MESSAGE;paintSlots();
  try{const req=indexedDB.open('cida-daily-collage',1);req.onupgradeneeded=()=>req.result.createObjectStore('daily');req.onsuccess=()=>{const db=req.result,tx=db.transaction('daily','readonly'),get=tx.objectStore('daily').get('slots');get.onsuccess=()=>{if(!revision&&Array.isArray(get.result)&&get.result.length===4){slots=get.result.map(s=>s&&s.blob instanceof Blob?{title:String(s.title||'Promo CIDA'),blob:s.blob}:null);invalidate();paintSlots()}};tx.oncomplete=()=>db.close()}}catch{}
  window.CidaDailyHelpers={validateLink,extractLink,messageWithLink,compressCollage,LIMIT};
})();
